const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
const date1 = `${yyyy}-${mm}-${dd}`;

return [{ json: { date1 } }];

const xmlData = $input.first().json.data;
const rows = xmlData.match(/<TR>([\s\S]*?)<\/TR>/g) || [];

// === 매장 정보 (워크플로우별로 여기만 수정) ===
const SHOP_CD = 'STORE_CODE_1';
const SHOP_NM = '아이스팝1호점';
// ===========================================

const result = [];

rows.forEach(row => {
  const cells = row.match(/<TD><!\[CDATA\[(.*?)\]\]><\/TD>/g) || [];
  const values = cells.map(cell => cell.match(/<TD><!\[CDATA\[(.*?)\]\]><\/TD>/)[1]);

  // values[0]은 체크박스(빈 값), values[1]부터 데이터
  // 매핑: 1=SHOP_CD, 2=SHOP_NM, 3=SALE_DATE, 4=POS_NO, 5=BILL_NO, 6=DTL_NO,
  //       7=BRAND_CD, 8=BRAND_NM, 9=PROD_CD, 10=BAR_CD, 11=PROD_NM,
  //       12=SALE_AMT, 13=DC_AMT, 14=DCM_SALE_AMT

  if (!values[5]) return; // BILL_NO 없으면 빈 행

  const SALE_DATE_RAW = values[3];
  const SALE_DATE = SALE_DATE_RAW.includes('-')
    ? SALE_DATE_RAW
    : `${SALE_DATE_RAW.slice(0,4)}-${SALE_DATE_RAW.slice(4,6)}-${SALE_DATE_RAW.slice(6,8)}`;

  const POS_NO = values[4];
  const BILL_NO = values[5];
  const DTL_NO = values[6];
  const BAR_CD = values[10];
  const PROD_NM = values[11];
  const SALE_AMT = parseInt(values[12]) || 0;
  const DC_AMT = parseInt(values[13]) || 0;
  const DCM_SALE_AMT = parseInt(values[14]) || 0;

  const 중복방지키 = `${SALE_DATE.replace(/-/g, '')}_${SHOP_CD}_${POS_NO}_${BILL_NO}_${DTL_NO}`;

  result.push({
    json: {
      매출일자: SALE_DATE,
      매장코드: SHOP_CD,
      매장명: SHOP_NM,
      포스: POS_NO,
      영수: BILL_NO,
      순번: DTL_NO,
      바코드: BAR_CD,
      상품명: PROD_NM,
      총매출: SALE_AMT,
      할인액: DC_AMT,
      실매출: DCM_SALE_AMT,
      중복방지키
    }
  });
});

return result;
